import React from 'react';
import { View, StyleSheet, TouchableOpacity, Animated, ScrollView } from 'react-native';
import { createStackNavigator } from '@react-navigation/stack';
import { useNavigation } from '@react-navigation/native';
import { LinearGradient } from 'expo-linear-gradient';

import MaterialCommunityIcons from 'react-native-vector-icons/MaterialCommunityIcons';
import MaterialIcons from 'react-native-vector-icons/MaterialIcons';
import Feather from 'react-native-vector-icons/Feather';

import SplashLogoScreen from '../screens/SplashLogoScreen';
import TelaInicio from '../screens/Inicio';
import TelaCriarEscala from '../screens/TelaCriarEscala';
import TelaListaEscalas from '../screens/TelaListaEscalas';
import TelaDetalhesEscala from '../screens/DetalhesEscala';
import RepertoiresScreen from '../screens/Repertorios';
import AdicionarRepertorio from '../screens/AdicionarRepertorio';
import DetalheRepertorio from '../screens/DetalheRepertorio';
import VisualizarArquivo from '../screens/VisualizarArquivo';
import PresencaScreen from '../screens/Presenca';
import AvisosScreen from '../screens/Avisos';
import EnsaiosScreen from '../screens/Ensaios';
import TelaAniversariantes from '../screens/Aniversariantes';
import TelaAgenda from '../screens/Agenda';

const Stack = createStackNavigator();
const GRADIENTE_BARRA = ['#2b323d', '#19202a', '#111821'];
const COR_ICONE_INATIVO = 'rgba(135, 149, 164, 0.48)';
const COR_ICONE_ATIVO = '#FFFFFF';
const COR_ICONE_CENTRAL = 'rgba(107, 161, 163, 0.78)';

const neuMorphShadow = {
  shadowColor: '#000',
  shadowOffset: { width: 0, height: 12 },
  shadowOpacity: 0.38,
  shadowRadius: 22,
  elevation: 18,
};

const BarraNavegacaoFixa = () => {
  const navegacao = useNavigation();
  const estadoNavegacao = navegacao.getState();
  const rotaAtual = estadoNavegacao?.routes[estadoNavegacao.index]?.name || '';

  const itens = React.useMemo(() => [
    { biblioteca: 'materialCommunity', nome: 'bell-ring-outline', rota: 'Avisos', texto: 'Avisos' },
    { biblioteca: 'materialCommunity', nome: 'music-box-multiple-outline', rota: 'Repertorios', texto: 'Repertorios' },
    { biblioteca: 'material', nome: 'event', rota: 'Escalas', texto: 'Escalas' },
    { biblioteca: 'feather', nome: 'plus', rota: 'CriarEscala', texto: 'Criar' },
    { biblioteca: 'materialCommunity', nome: 'home', rota: 'Inicio', texto: 'Inicio' },
    { biblioteca: 'feather', nome: 'user-check', rota: 'Presenca', texto: 'Presenca' },
    { biblioteca: 'feather', nome: 'users', rota: 'Ensaios', texto: 'Ensaios' },
    { biblioteca: 'materialCommunity', nome: 'gift-outline', rota: 'Aniversariantes', texto: 'Aniversariantes' },
    { biblioteca: 'material', nome: 'calendar-today', rota: 'Agenda', texto: 'Agenda' },
  ], []);

  const animEscala = React.useRef(
    Array(itens.length).fill(0).map(() => new Animated.Value(1))
  ).current;

  React.useEffect(() => {
    itens.forEach((item, indice) => {
      const selecionado = item.rota === rotaAtual;
      animEscala[indice].stopAnimation();

      if (selecionado) {
        Animated.loop(
          Animated.sequence([
            Animated.timing(animEscala[indice], {
              toValue: 1.16,
              duration: 650,
              useNativeDriver: true,
            }),
            Animated.timing(animEscala[indice], {
              toValue: 1.02,
              duration: 650,
              useNativeDriver: true,
            }),
          ])
        ).start();
        return;
      }

      Animated.spring(animEscala[indice], {
        toValue: 1,
        friction: 8,
        tension: 50,
        useNativeDriver: true,
      }).start();
    });
  }, [rotaAtual, itens, animEscala]);

  if (rotaAtual === 'SplashLogo') return null;

  return (
    <LinearGradient
      colors={GRADIENTE_BARRA}
      start={{ x: 0, y: 0 }}
      end={{ x: 0, y: 1 }}
      style={estilos.barraNavegacao}
    >
      <ScrollView
        horizontal
        showsHorizontalScrollIndicator={false}
        contentContainerStyle={estilos.conteudoScroll}
      >
        {itens.map((item, indice) => {
          const selecionado = item.rota === rotaAtual;
          const corIcone = selecionado
            ? COR_ICONE_ATIVO
            : item.nome === 'plus'
              ? COR_ICONE_CENTRAL
              : COR_ICONE_INATIVO;
          const tamanho = item.nome === 'plus' ? 24 : 22;

          return (
            <TouchableOpacity
              key={item.rota}
              style={estilos.itemBarra}
              activeOpacity={0.85}
              accessibilityLabel={item.texto}
              onPress={() => navegacao.navigate(item.rota as never)}
            >
              <Animated.View
                style={[
                  estilos.containerIconeBase,
                  selecionado && estilos.itemAtivo,
                  { transform: [{ scale: animEscala[indice] }] },
                ]}
              >
                {item.biblioteca === 'materialCommunity' && (
                  <MaterialCommunityIcons name={item.nome} size={tamanho} color={corIcone} />
                )}
                {item.biblioteca === 'material' && (
                  <MaterialIcons name={item.nome} size={tamanho} color={corIcone} />
                )}
                {item.biblioteca === 'feather' && (
                  <Feather name={item.nome} size={tamanho} color={corIcone} />
                )}
              </Animated.View>
            </TouchableOpacity>
          );
        })}
      </ScrollView>
    </LinearGradient>
  );
};

export default function AppNavigator() {
  return (
    <View style={estilos.containerPrincipal}>
      <View style={estilos.areaConteudo}>
        <Stack.Navigator initialRouteName="SplashLogo" screenOptions={{ headerShown: false }}>
          <Stack.Screen name="SplashLogo" component={SplashLogoScreen} />
          <Stack.Screen name="Inicio" component={TelaInicio} />
          <Stack.Screen name="CriarEscala" component={TelaCriarEscala} />
          <Stack.Screen name="Escalas" component={TelaListaEscalas} />
          <Stack.Screen name="DetalhesEscala" component={TelaDetalhesEscala} />
          <Stack.Screen name="Repertorios" component={RepertoiresScreen} />
          <Stack.Screen name="AdicionarRepertorio" component={AdicionarRepertorio} />
          <Stack.Screen name="DetalheRepertorio" component={DetalheRepertorio} />
          <Stack.Screen name="VisualizarArquivo" component={VisualizarArquivo} />
          <Stack.Screen name="Presenca" component={PresencaScreen} />
          <Stack.Screen name="Avisos" component={AvisosScreen} />
          <Stack.Screen name="Ensaios" component={EnsaiosScreen} />
          <Stack.Screen name="Aniversariantes" component={TelaAniversariantes} />
          <Stack.Screen name="Agenda" component={TelaAgenda} />
        </Stack.Navigator>
      </View>
      <BarraNavegacaoFixa />
    </View>
  );
}

const estilos = StyleSheet.create({
  containerPrincipal: {
    flex: 1,
    position: 'relative',
    backgroundColor: '#121212ea',
  },
  areaConteudo: {
    flex: 1,
    paddingBottom: 90,
  },
  barraNavegacao: {
    position: 'absolute',
    bottom: 8,
    left: 0,
    right: 0,
    minHeight: 64,
    borderRadius: 24,
    overflow: 'hidden',
    borderWidth: 1,
    borderTopColor: 'rgba(255,255,255,0.08)',
    borderLeftColor: 'rgba(255,255,255,0.04)',
    borderRightColor: 'rgba(0,0,0,0.2)',
    borderBottomColor: 'rgba(0,0,0,0.35)',
    ...neuMorphShadow,
  },
  conteudoScroll: {
    flexGrow: 1,
    alignItems: 'center',
    justifyContent: 'space-around',
    paddingHorizontal: 12,
    paddingVertical: 10,
    gap: 4,
  },
  itemBarra: {
    alignItems: 'center',
    justifyContent: 'center',
    width: 44,
    height: 44,
  },
  containerIconeBase: {
    width: 38,
    height: 38,
    justifyContent: 'center',
    alignItems: 'center',
    borderRadius: 19,
  },
  itemAtivo: {
    backgroundColor: 'rgba(255,255,255,0.045)',
  },
});
